int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    vector<pair<long long, string>> products(n); // (-popularity, name) sorts by the ranking
    for (auto &p : products) {
        long long pop;
        cin >> p.second >> pop;
        p.first = -pop;
    }
    string word;
    cin >> word;
    sort(products.begin(), products.end());
    vector<vector<int>> answer(word.size());
    for (int idx = 0; idx < n; idx++) {
        const string &name = products[idx].second;
        size_t lim = min(name.size(), word.size());
        // the product matches every prefix up to its common prefix with word
        for (size_t i = 0; i < lim && name[i] == word[i]; i++)
            if ((int)answer[i].size() < k) answer[i].push_back(idx);
    }
    string out;
    for (auto &row : answer) {
        out += to_string(row.size());
        for (int idx : row) { out += ' '; out += products[idx].second; }
        out += '\n';
    }
    cout << out;
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream is = System.in;

    static int readByte() throws IOException {
        if (ptr == len) { len = is.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = readByte();
        while (c != -1 && c <= ' ') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = readByte(); }
        return sb.toString();
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c != '-' && (c < '0' || c > '9')) c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = readByte(); }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong(), k = (int) nextLong();
        String[] names = new String[n];
        long[] pop = new long[n];
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) {
            names[i] = next();
            pop[i] = nextLong();
            order[i] = i;
        }
        String word = next();
        // ranking: popularity descending, then name ascending
        Arrays.sort(order, (x, y) -> pop[x] != pop[y] ? Long.compare(pop[y], pop[x]) : names[x].compareTo(names[y]));
        int L = word.length();
        int[][] answer = new int[L][k];
        int[] size = new int[L];
        for (int idx : order) {
            String name = names[idx];
            int lim = Math.min(name.length(), L);
            // the product matches every prefix up to its common prefix with word
            for (int i = 0; i < lim && name.charAt(i) == word.charAt(i); i++)
                if (size[i] < k) answer[i][size[i]++] = idx;
        }
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < L; i++) {
            out.append(size[i]);
            for (int j = 0; j < size[i]; j++) out.append(' ').append(names[answer[i][j]]);
            out.append('\n');
        }
        System.out.print(out);
    }
}

package main

import (
	"bufio"
	"os"
	"sort"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() string {
		sc.Scan()
		return sc.Text()
	}
	n, _ := strconv.Atoi(next())
	k, _ := strconv.Atoi(next())
	names := make([]string, n)
	pop := make([]int64, n)
	for i := 0; i < n; i++ {
		names[i] = next()
		pop[i], _ = strconv.ParseInt(next(), 10, 64)
	}
	word := next()
	order := make([]int, n)
	for i := range order {
		order[i] = i
	}
	// ranking: popularity descending, then name ascending
	sort.Slice(order, func(a, b int) bool {
		x, y := order[a], order[b]
		if pop[x] != pop[y] {
			return pop[x] > pop[y]
		}
		return names[x] < names[y]
	})
	answer := make([][]int, len(word))
	for _, idx := range order {
		name := names[idx]
		lim := min(len(name), len(word))
		// the product matches every prefix up to its common prefix with word
		for i := 0; i < lim && name[i] == word[i]; i++ {
			if len(answer[i]) < k {
				answer[i] = append(answer[i], idx)
			}
		}
	}
	w := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer w.Flush()
	for _, row := range answer {
		w.WriteString(strconv.Itoa(len(row)))
		for _, idx := range row {
			w.WriteByte(' ')
			w.WriteString(names[idx])
		}
		w.WriteByte('\n')
	}
}
